import services.BookService;
import services.UserService;
import services.LoanService;
import database.DatabaseManager;

public class TestPersistence {
    public static void main(String[] args) {
        System.out.println("=== Test de la persistance SQLite ===\n");

        // Initialiser la base de données
        DatabaseManager dbManager = DatabaseManager.getInstance();

        // Test 1 : Ajouter des livres
        System.out.println("1. Ajout de livres...");
        BookService.addBook("1984", "George Orwell", "Science-Fiction");
        BookService.addBook("Le Petit Prince", "Antoine de Saint-Exupéry", "Conte");
        BookService.addBook("Harry Potter", "J.K. Rowling", "Fantasy");

        // Test 2 : Ajouter des utilisateurs
        System.out.println("\n2. Ajout d'utilisateurs...");
        UserService.addUser("Alice Dupont", "alice@mail.com");
        UserService.addUser("Bob Martin", "bob@mail.com");

        // Test 3 : Lister les livres
        System.out.println("\n3. Liste des livres :");
        BookService.listBooks();

        // Test 4 : Lister les utilisateurs
        System.out.println("\n4. Liste des utilisateurs :");
        UserService.listUsers();

        // Test 5 : Emprunter un livre
        System.out.println("\n5. Emprunt d'un livre...");
        LoanService.borrowBook(1, 1); // Alice emprunte 1984

        // Test 6 : Lister les livres disponibles vs empruntés
        System.out.println("\n6. Livres disponibles :");
        BookService.listAvailableBooks();

        System.out.println("\n7. Livres empruntés :");
        BookService.listBorrowedBooks();

        // Test 7 : Lister les emprunts
        System.out.println("\n8. Liste des emprunts :");
        LoanService.listLoans();

        // Test 8 : Recherche par titre
        System.out.println("\n9. Recherche par titre (Harry) :");
        BookService.searchByTitle("Harry");

        // Test 9 : Recherche par auteur
        System.out.println("\n10. Recherche par auteur (Orwell) :");
        BookService.searchByAuthor("Orwell");

        // Test 10 : Historique d'un utilisateur
        System.out.println("\n11. Historique des emprunts d'Alice :");
        UserService.showUserLoanHistory(1);

        // Test 11 : Retourner un livre
        System.out.println("\n12. Retour d'un livre...");
        LoanService.returnBook(1);

        // Test 12 : Vérifier que le livre est à nouveau disponible
        System.out.println("\n13. Livres disponibles après retour :");
        BookService.listAvailableBooks();

        // Test 13 : Tester le conflit (livre déjà emprunté)
        System.out.println("\n14. Test de conflit - emprunter deux fois le même livre :");
        LoanService.borrowBook(2, 1); // Alice emprunte Le Petit Prince
        LoanService.borrowBook(2, 2); // Bob essaye d'emprunter Le Petit Prince (déjà emprunté)

        System.out.println("\n✅ Tous les tests de persistance sont terminés !");
        System.out.println(" Vérifiez que les données sont bien dans library.db");
        System.out.println(" Relancez ce test pour vérifier que les données persistent !");

        dbManager.close();
    }
}

package models;

public class User {
    private int id;
    private String name;
    private String email;

    public User(int id, String name, String email) {
        this.id = id;
        this.name = name;
        this.email = email;
    }

    // Getters
    public int getId() { return id; }
    public String getName() { return name; }
    public String getEmail() { return email; }

    // Setters
    public void setName(String name) { this.name = name; }
    public void setEmail(String email) { this.email = email; }

    @Override
    public String toString() {
        return String.format("[%d] %s (%s)", id, name, email);
    }
}

package models;

